) i32 {
    const allocator = std.heap.page_allocator;
    const seq1 = seq1_ptr[0..seq1_len];
    const seq2 = seq2_ptr[0..seq2_len];

    var alignment = smithWaterman(allocator, seq1, seq2, gap_penalty) catch return -1;
    defer alignment.deinit(allocator);

    return alignment.score;
}

