pub fn smithWaterman(
    allocator: std.mem.Allocator,
    seq1: []const u8,
    seq2: []const u8,
    gap_penalty: i32,
) !SequenceAlignment {
    const rows = seq1.len + 1;
    const cols = seq2.len + 1;

    const score_matrix = try allocator.alloc([]i32, rows);
    defer allocator.free(score_matrix);

    for (score_matrix, 0..) |*row, i| {
        row.* = try allocator.alloc(i32, cols);
    }
    defer for (score_matrix) |row| allocator.free(row);

    for (score_matrix[0]) |*cell| {
        cell.* = 0;
    }
    for (score_matrix) |row| {
        row[0] = 0;
    }

    var max_score: i32 = 0;
    var max_i: usize = 0;
    var max_j: usize = 0;

    var i: usize = 1;
    while (i < rows) : (i += 1) {
        var j: usize = 1;
        while (j < cols) : (j += 1) {
            const aa1 = seq1[i - 1];
            const aa2 = seq2[j - 1];

            const match_score = if (aa1 == aa2) @as(i32, 5) else @as(i32, -3);

            const diag = score_matrix[i - 1][j - 1] + match_score;
            const up = score_matrix[i - 1][j] + gap_penalty;
            const left = score_matrix[i][j - 1] + gap_penalty;

            score_matrix[i][j] = @max(0, @max(diag, @max(up, left)));

            if (score_matrix[i][j] > max_score) {
                max_score = score_matrix[i][j];
                max_i = i;
                max_j = j;
            }
        }
    }

    var aligned1 = std.ArrayList(u8).init(allocator);
    var aligned2 = std.ArrayList(u8).init(allocator);

    i = max_i;
    var j = max_j;

    while (i > 0 and j > 0 and score_matrix[i][j] > 0) {
        const current = score_matrix[i][j];
        const diag = score_matrix[i - 1][j - 1];
        const up = score_matrix[i - 1][j];
        const left = score_matrix[i][j - 1];

        if (current == diag + (if (seq1[i - 1] == seq2[j - 1]) @as(i32, 5) else @as(i32, -3))) {
            try aligned1.append(seq1[i - 1]);
            try aligned2.append(seq2[j - 1]);
            i -= 1;
            j -= 1;
        } else if (current == up + gap_penalty) {
            try aligned1.append(seq1[i - 1]);
            try aligned2.append('-');
            i -= 1;
        } else {
            try aligned1.append('-');
            try aligned2.append(seq2[j - 1]);
            j -= 1;
        }
    }

    std.mem.reverse(u8, aligned1.items);
    std.mem.reverse(u8, aligned2.items);

    const identity = calculateIdentity(aligned1.items, aligned2.items);
    const similarity = calculateSimilarity(aligned1.items, aligned2.items);

    return SequenceAlignment{
        .score = max_score,
        .aligned_seq1 = try aligned1.toOwnedSlice(),
        .aligned_seq2 = try aligned2.toOwnedSlice(),
        .identity = identity,
        .similarity = similarity,
    };
}

fn calculateIdentity(seq1: []const u8, seq2: []const u8) f32 {
    if (seq1.len == 0) return 0.0;

    var matches: usize = 0;
    for (seq1, seq2) |a1, a2| {
        if (a1 == a2 and a1 != '-') {
            matches += 1;
        }
    }

    return @as(f32, @floatFromInt(matches)) / @as(f32, @floatFromInt(seq1.len));
}

fn calculateSimilarity(seq1: []const u8, seq2: []const u8) f32 {
    if (seq1.len == 0) return 0.0;

    var similar: usize = 0;
    for (seq1, seq2) |a1, a2| {
        if (a1 != '-' and a2 != '-') {
            const idx1 = aaToIndex(a1);
            const idx2 = aaToIndex(a2);
            if (idx1 < 20 and idx2 < 20) {
                if (BLOSUM62[idx1][idx2] > 0) {
                    similar += 1;
                }
            }
        }
    }

    return @as(f32, @floatFromInt(similar)) / @as(f32, @floatFromInt(seq1.len));
}

fn aaToIndex(aa: u8) usize {
    return switch (aa) {
        'A' => 0, 'R' => 1, 'N' => 2, 'D' => 3, 'C' => 4,
        'Q' => 5, 'E' => 6, 'G' => 7, 'H' => 8, 'I' => 9,
        'L' => 10, 'K' => 11, 'M' => 12, 'F' => 13, 'P' => 14,
        'S' => 15, 'T' => 16, 'W' => 17, 'Y' => 18, 'V' => 19,
        else => 20,
    };
}

pub export fn zig_sequence_align(
    seq1_ptr: [*]const u8,
    seq1_len: usize,
    seq2_ptr: [*]const u8,
    seq2_len: usize,
    gap_penalty: i32,
) i32 {
    const allocator = std.heap.page_allocator;
    const seq1 = seq1_ptr[0..seq1_len];
    const seq2 = seq2_ptr[0..seq2_len];

    var alignment = smithWaterman(allocator, seq1, seq2, gap_penalty) catch return -1;
    defer alignment.deinit(allocator);

    return alignment.score;
}

pub export fn zig_calculate_sequence_identity(
    seq1_ptr: [*]const u8,
    seq1_len: usize,
    seq2_ptr: [*]const u8,
    seq2_len: usize,
) f32 {
    const seq1 = seq1_ptr[0..seq1_len];
    const seq2 = seq2_ptr[0..seq2_len];
    return calculateIdentity(seq1, seq2);
}

pub export fn zig_validate_protein_sequence(seq_ptr: [*]const u8, seq_len: usize) bool {
    const seq = seq_ptr[0..seq_len];
    const valid_aas = "ARNDCQEGHILKMFPSTWYV";

    for (seq) |aa| {
        var found = false;
        for (valid_aas) |valid| {
            if (aa == valid) {
                found = true;
                break;
            }
        }
        if (!found) return false;
    }

    return true;
}
